import{_ as e,o as a,c as i,ao as r}from"./chunks/framework.BrCix5Tt.js";const d="/UpdatableFactorizations.jl/dev/assets/bench-cholesky.RX5rtF0q.svg",s="/UpdatableFactorizations.jl/dev/assets/bench-lu.Cpell9LR.svg",o="/UpdatableFactorizations.jl/dev/assets/bench-qr.B5spAMVi.svg",m=JSON.parse('{"title":"Benchmarks","description":"","frontmatter":{},"headers":[],"relativePath":"benchmarks.md","filePath":"benchmarks.md","lastUpdated":null}'),n={name:"benchmarks.md"};function l(h,t,c,g,x,y){return a(),i("div",null,[...t[0]||(t[0]=[r(`<p>&lt;!– Generated by bench/plot_results.jl from bench/results. Edit the script, not this file. –&gt;</p><h1 id="Benchmarks" tabindex="-1">Benchmarks <a class="header-anchor" href="#Benchmarks" aria-label="Permalink to &quot;Benchmarks {#Benchmarks}&quot;">​</a></h1><p>Every number on this page comes from a recorded sample file under <code>bench/results/</code>, written by <code>bench/updating_sweep.jl</code> with BLAS restricted to one thread. <code>bench/plot_results.jl</code> reads those files and writes this page and its figures; it runs no benchmark of its own. To reproduce the whole thing from a checkout:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>julia --project=bench bench/setup.jl</span></span>
<span class="line"><span>julia --project=bench bench/updating_sweep.jl</span></span>
<span class="line"><span>julia --project=bench bench/plot_results.jl</span></span></code></pre></div><h2 id="What-is-compared,-and-which-way-the-ratios-point" tabindex="-1">What is compared, and which way the ratios point <a class="header-anchor" href="#What-is-compared,-and-which-way-the-ratios-point" aria-label="Permalink to &quot;What is compared, and which way the ratios point {#What-is-compared,-and-which-way-the-ratios-point}&quot;">​</a></h2><p>Every ratio on this page is a reference time divided by the time of the row it sits next to: <strong>above 1.00 means that row is faster than the reference, below 1.00 means it is slower.</strong> For an updating verb the reference is <code>recompute</code> – throwing the factorization away and calling <code>cholesky</code>, <code>lu</code> or <code>qr</code> again on the modified matrix, in the &quot;vs recomputing&quot; column below. That is the package&#39;s central claim: whether keeping a factorization current is worth it compared to starting over. A verdict table precedes each family&#39;s detail table and states, per routine, the range of that ratio across the sizes measured and at which sizes, if any, updating loses.</p><p>Two of the prior-art comparisons do a different amount of work than the row they sit next to, and are marked wherever their numbers appear, not only here: <code>QRupdate</code> maintains <code>R</code> alone, from the normal equations, and never forms or updates <code>Q</code>, so it does strictly less work. <code>UpdatableQRFactorizations</code> maintains a full <code>m x m</code> <code>Q</code> where this package maintains a thin <code>m x n</code> one, so it does strictly more work.</p><p>Building a factorization from scratch goes through <code>LinearAlgebra</code>. This package&#39;s own construction routines run from 0.51x to 1.61x the speed of the blocked LAPACK routine they are compared against, where 1.00 is parity: most of those cells are slower and one is faster. See <a href="/UpdatableFactorizations.jl/dev/construction#Construction">Construction</a> for which routine and why.</p><p>Recorded with governor <code>powersave</code>, Julia 1.12.7, LBTConfig([ILP64] libopenblas64_.so, [LP64] libopenblas.so), 1 BLAS thread, 2026-09-10, commit <code>f06bb78</code>.</p><h2 id="Cholesky" tabindex="-1">Cholesky <a class="header-anchor" href="#Cholesky" aria-label="Permalink to &quot;Cholesky {#Cholesky}&quot;">​</a></h2><p><img src="`+d+'" alt=""></p><table tabindex="0"><thead><tr><th style="text-align:right;">routine</th><th style="text-align:right;">worst</th><th style="text-align:right;">best</th><th style="text-align:right;">vs recomputing</th><th style="text-align:right;">vs the fastest other implementation</th></tr></thead><tbody><tr><td style="text-align:right;"><code>lowrankupdate!</code></td><td style="text-align:right;">6.32x</td><td style="text-align:right;">44.14x</td><td style="text-align:right;">wins at every n measured</td><td style="text-align:right;">1.19x-2.71x faster than <code>LinearAlgebra</code></td></tr><tr><td style="text-align:right;"><code>lowrankdowndate!</code></td><td style="text-align:right;">3.04x</td><td style="text-align:right;">27.67x</td><td style="text-align:right;">wins at every n measured</td><td style="text-align:right;">1.05x-2.57x faster than <code>LinearAlgebra</code></td></tr><tr><td style="text-align:right;"><code>delete_column!</code></td><td style="text-align:right;">1.58x</td><td style="text-align:right;">5.97x</td><td style="text-align:right;">wins at every n measured</td><td style="text-align:right;">3.15x-5.15x faster than <code>UpdatableCholeskyFactorizations</code></td></tr><tr><td style="text-align:right;"><code>append_column!</code></td><td style="text-align:right;">11.92x</td><td style="text-align:right;">77.08x</td><td style="text-align:right;">wins at every n measured</td><td style="text-align:right;">0.53x-1.26x of <code>UpdatableCholeskyFactorizations</code>, slower at n = 256, 1024</td></tr><tr><td style="text-align:right;"><code>insert_column!</code></td><td style="text-align:right;">2.88x</td><td style="text-align:right;">16.81x</td><td style="text-align:right;">wins at every n measured</td><td style="text-align:right;">no other implementation measured</td></tr><tr><td style="text-align:right;"><code>shift_columns!</code></td><td style="text-align:right;">3.85x</td><td style="text-align:right;">19.20x</td><td style="text-align:right;">wins at every n measured</td><td style="text-align:right;">no other implementation measured</td></tr></tbody></table><h2 id="LU" tabindex="-1">LU <a class="header-anchor" href="#LU" aria-label="Permalink to &quot;LU {#LU}&quot;">​</a></h2><p><img src="'+s+'" alt=""></p><table tabindex="0"><thead><tr><th style="text-align:right;">routine</th><th style="text-align:right;">worst</th><th style="text-align:right;">best</th><th style="text-align:right;">vs recomputing</th><th style="text-align:right;">vs the fastest other implementation</th></tr></thead><tbody><tr><td style="text-align:right;"><code>lowrankupdate! nopivot</code></td><td style="text-align:right;">28.58x</td><td style="text-align:right;">278.57x</td><td style="text-align:right;">wins at every n measured</td><td style="text-align:right;">3.21x-5.89x faster than <code>QRupdatesFast</code></td></tr><tr><td style="text-align:right;"><code>lowrankupdate! pivoted</code></td><td style="text-align:right;">10.02x</td><td style="text-align:right;">32.98x</td><td style="text-align:right;">wins at every n measured</td><td style="text-align:right;">2.60x-40.24x faster than <code>QRupdatesFast</code></td></tr></tbody></table><h2 id="QR" tabindex="-1">QR <a class="header-anchor" href="#QR" aria-label="Permalink to &quot;QR {#QR}&quot;">​</a></h2><p><img src="'+o+'" alt=""></p><table tabindex="0"><thead><tr><th style="text-align:right;">routine</th><th style="text-align:right;">worst</th><th style="text-align:right;">best</th><th style="text-align:right;">vs recomputing</th><th style="text-align:right;">vs the fastest other implementation</th></tr></thead><tbody><tr><td style="text-align:right;"><code>lowrankupdate!</code></td><td style="text-align:right;">4.00x</td><td style="text-align:right;">10.17x</td><td style="text-align:right;">wins at every m measured</td><td style="text-align:right;">no other implementation measured</td></tr><tr><td style="text-align:right;"><code>insert_column!</code></td><td style="text-align:right;">20.52x</td><td style="text-align:right;">43.65x</td><td style="text-align:right;">wins at every m measured</td><td style="text-align:right;">0.75x-2.37x of <code>QRupdate</code> (which maintains <code>R</code> only, never <code>Q</code>), slower at m = 2048</td></tr><tr><td style="text-align:right;"><code>delete_column!</code></td><td style="text-align:right;">12.12x</td><td style="text-align:right;">21.78x</td><td style="text-align:right;">wins at every m measured</td><td style="text-align:right;">0.87x-1.71x of <code>QRupdate</code> (which maintains <code>R</code> only, never <code>Q</code>), slower at m = 256</td></tr><tr><td style="text-align:right;"><code>shift_columns!</code></td><td style="text-align:right;">16.63x</td><td style="text-align:right;">37.53x</td><td style="text-align:right;">wins at every m measured</td><td style="text-align:right;">0.55x-1.06x of <code>QRupdatesFast</code>, slower at m = 256, 1024, 2048</td></tr><tr><td style="text-align:right;"><code>insert_row!</code></td><td style="text-align:right;">16.84x</td><td style="text-align:right;">27.47x</td><td style="text-align:right;">wins at every m measured</td><td style="text-align:right;">1.91x-4.94x faster than <code>QRupdate</code> (which maintains <code>R</code> only, never <code>Q</code>)</td></tr><tr><td style="text-align:right;"><code>delete_row!</code></td><td style="text-align:right;">6.34x</td><td style="text-align:right;">11.91x</td><td style="text-align:right;">wins at every m measured</td><td style="text-align:right;">no other implementation measured</td></tr></tbody></table>',18)])])}const u=e(n,[["render",l]]);export{m as __pageData,u as default};
